package com.efgenbosh.backend.controller;
import com.efgenbosh.backend.domain.VehicleMake; import com.efgenbosh.backend.domain.VehicleModel; import com.efgenbosh.backend.dto.directory.VehicleCatalogItemRequest; import com.efgenbosh.backend.repository.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/v1/directories/vehicle-catalog")
public class VehicleCatalogController { private final VehicleMakeRepository makes; private final VehicleModelRepository models; public VehicleCatalogController(VehicleMakeRepository makes, VehicleModelRepository models){this.makes=makes;this.models=models;} @GetMapping("/makes") public List<?> makes(){return makes.findAllByActiveTrueOrderByNameAsc().stream().map(x->new Item(x.getId(),x.getName())).toList();} @GetMapping("/models") public List<?> models(@RequestParam Long makeId){return models.findAllByMake_IdAndActiveTrueOrderByNameAsc(makeId).stream().map(x->new Item(x.getId(),x.getName())).toList();} @PostMapping("/makes") @ResponseStatus(HttpStatus.CREATED) public Item createMake(@Valid @RequestBody VehicleCatalogItemRequest request){ if(makes.existsByNameIgnoreCase(request.name().trim())) throw new ResponseStatusException(HttpStatus.CONFLICT,"Такая марка уже существует."); VehicleMake item=new VehicleMake(); item.setName(request.name().trim()); item=makes.save(item); return new Item(item.getId(),item.getName()); } @PutMapping("/makes/{id}") public Item updateMake(@PathVariable Long id,@Valid @RequestBody VehicleCatalogItemRequest request){VehicleMake item=makes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Марка не найдена.")); item.setName(request.name().trim()); item=makes.save(item); return new Item(item.getId(),item.getName());} @DeleteMapping("/makes/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteMake(@PathVariable Long id){makes.findById(id).ifPresent(item->{item.setActive(false);makes.save(item);});} @PostMapping("/models") @ResponseStatus(HttpStatus.CREATED) public Item createModel(@Valid @RequestBody VehicleCatalogItemRequest request){VehicleMake make=makes.findById(request.makeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Марка не найдена.")); if(models.existsByMake_IdAndNameIgnoreCase(make.getId(),request.name().trim())) throw new ResponseStatusException(HttpStatus.CONFLICT,"Такая модель уже существует у этой марки."); VehicleModel item=new VehicleModel(); item.setMake(make); item.setName(request.name().trim()); item=models.save(item); return new Item(item.getId(),item.getName());} @PutMapping("/models/{id}") public Item updateModel(@PathVariable Long id,@Valid @RequestBody VehicleCatalogItemRequest request){VehicleModel item=models.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Модель не найдена.")); item.setName(request.name().trim()); if(request.makeId()!=null) item.setMake(makes.findById(request.makeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Марка не найдена."))); return new Item(item.getId(),models.save(item).getName());} @DeleteMapping("/models/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteModel(@PathVariable Long id){models.findById(id).ifPresent(item->{item.setActive(false);models.save(item);});} record Item(Long id,String name){} }
